const data = $item(0).$node["Compara Get Memory"].json["Redis2"];
let array = Array.isArray(data) ? data : JSON.parse(data);

// Une todas as mensagens do array em um único texto
const texto = array.join("\n");

// 1. Captura o número da mesa
const matchMesa = texto.match(/mesa\s+(\d+)/i);
const numeroMesa = matchMesa ? matchMesa[1] : null;

// 2. Captura o nome do restaurante
let nomeRestaurante = "Não encontrado";
const matchRestaurante = texto.match(/(?:no|na|do|da)\s+(?!mesa\s+\d+)(.+?)(?=\n|$|\.|\!)/i);

if (matchRestaurante) {
  let raw = matchRestaurante[1].trim();
  raw = raw.replace(/\b(restaurante|bar e lanchonete|lanchonete|bar)\b/ig, "").trim();
  if (raw.length > 0) {
    nomeRestaurante = raw.charAt(0).toUpperCase() + raw.slice(1);
  }
}

// 3. Verifica se tem mensagem de check-in
const tem_checkin = (numeroMesa !== null || nomeRestaurante !== "Não encontrado");

// 4. Verifica se tem algo além do check-in
// Remove a saudação comum e os dados de mesa/restaurante para ver se sobra texto
let limpeza = texto.replace(/Olá|estou|na|no|mesa|\d+|Liderança|Bar|e|Lanchonete|[.,!]/gi, "").trim();
const tem_conteudo_extra = limpeza.length > 5; // True se sobrar mais de 5 caracteres (evita falsos positivos com espaços/pontos)

return [{
  json: {
    mensagem_completa: texto,
    numero_mesa: numeroMesa,
    nome_restaurante: nomeRestaurante,
    tem_checkin: tem_checkin,
    tem_conteudo_extra: tem_conteudo_extra
  }
}];
